function out_out = mfun_gfl_pll(meas_in, u_c_ab_in, p)
%MFUN_GFL_PLL Block PLL of the control system.
%   PLL of motulator. Generated by motulator_export from the MATLAB port of motulator
%   and called by the MATLAB Function block of the library of motulator, whose folder
%   motulator.setup adds to the MATLAB path. The parameters are the fields of the struct
%   p (from the mask, [] as NaN). The state is in persistent variables, of which each
%   MATLAB Function block has its own copy.
persistent self
if isempty(self)
    self = pll_init(p.u_nom, p.w_nom, p.alpha_pll);
end
meas = grid_measurements_unpack(meas_in);
u_c_ab = complex_in(u_c_ab_in);
out = pll_compute_output(self, meas.i_c_ab, meas.u_g_ab);
% Voltage for the control laws (GridConverterControlSystem.get_feedback)
out.u_c = exp(-1i*out.theta_c)*u_c_ab;
out_out = gfl_feedbacks_pack(out);
self = pll_update(self, p.T_s, out);
end

function s = grid_measurements_unpack(u)
%GRID_MEASUREMENTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_c_ab', complex(u(1), u(2)), ...
    'u_g_ab', complex(u(3), u(4)), ...
    'u_dc', u(5));
end

function y = gfl_feedbacks_pack(s)
%GFL_FEEDBACKS_PACK Signal vector of the struct s.
y = [ ...
    real(s.i_c);
    imag(s.i_c);
    real(s.u_c);
    imag(s.u_c);
    s.u_g;
    real(s.u_g_meas);
    imag(s.u_g_meas);
    s.theta_c;
    s.w_g;
    s.w_c;
    s.p_g;
    s.q_g;
    s.eps];
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function theta = wrap(theta)
%WRAP Limit the angle into the range [-pi, pi), as numpy.mod does.
x = rem(theta + pi, 2*pi);
if x < 0
    x = x + 2*pi;
end
theta = x - pi;
end

function self = pll_init(u_nom, w_nom, alpha_pll)
%PLL_INIT Phase-locked loop with the voltage-magnitude filtering (PLL).
self = struct('k_p', 2*alpha_pll, 'k_i', alpha_pll*alpha_pll, 'w_g', w_nom, ...
    'theta_c', 0, 'u_g', u_nom);
end

function out = pll_compute_output(self, i_c_ab, u_g_ab)
%PLL_COMPUTE_OUTPUT Feedback signals (PLLOutputs) from the converter current and the
%   PCC voltage in stationary coordinates (the field u_c is zero, and u_dc is not
%   included).
theta_c = self.theta_c;
w_g = self.w_g;
% Coordinate transformations
rot = exp(-1i*theta_c);
i_c = rot*i_c_ab;
u_g_meas = rot*u_g_ab;
% Filtered voltage magnitude
u_g = self.u_g;
% Error signal and the angular speed of the coordinate system
if self.u_g > 0
    eps = imag(u_g_meas)/self.u_g;
else
    eps = 0;
end
w_c = w_g + self.k_p*eps;
% Powers
s_g = 1.5*u_g*conj(i_c);
out = struct('i_c', i_c, 'u_c', complex(0), 'u_g', u_g, 'u_g_meas', u_g_meas, ...
    'theta_c', theta_c, 'w_g', w_g, 'w_c', w_c, 'p_g', real(s_g), ...
    'q_g', imag(s_g), 'eps', eps);
end

function self = pll_update(self, T_s, out)
%PLL_UPDATE Update the angle, the frequency, and the voltage-magnitude estimates.
self.theta_c = wrap(self.theta_c + T_s*out.w_c);
self.w_g = self.w_g + T_s*self.k_i*out.eps;
self.u_g = self.u_g + T_s*self.k_p*(real(out.u_g_meas) - self.u_g);
end
